package rfcserver

import (
	"bytes"
	"context"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"net"

	"github.com/oisee/open-rfc-go/internal/transport"
)

// The handshake constants below were distilled from live A4H captures: the
// 817-byte CPIC logon-accept and the RFC_PING/RSRFCPIN response steps are 97%
// server-identity constant, so they are baked in and only the per-session tokens
// (conversation id, RFC GUID) are patched at runtime. smartGolden* are the token
// values these templates were captured with, replaced with the live client's.
var smartAccept, _ = hex.DecodeString("")
var smartPingSteps = [][]byte{
	mustHex(""),
	mustHex(""),
	mustHex(""),
	mustHex(""),
}
var smartGoldenGUID = mustHex("6a85a2ce99600b52e1000000ac110003")
var smartGoldenConv = mustHex("3637333931383031")

func mustHex(s string) []byte { b, _ := hex.DecodeString(s); return b }

// ServeSmart answers a live SM59 type-3 client as a small state machine, without
// replaying a capture file: it GENERATES each reply from a baked template by
// mirroring the client's session tokens.
//
//	CONNECT  a 64-byte gateway record -> reply with bytes 29,55 set (capability ack)
//	LOGON    a CPIC-init record       -> generate the logon-accept for this session
//	SESSION  an F_SAP_SEND with data  -> answer the RFC_PING/RSRFCPIN step
//	         (a fresh CPIC-init on the same pooled socket -> back to LOGON)
//
// RFC_PING is handled as a recurring SESSION event, since a peer may ping to
// check liveness at any time — not only during a Connection Test.
func ServeSmart(conn net.Conn, logf func(string)) {
	defer conn.Close()
	log := func(s string) {
		if logf != nil {
			logf(s)
		}
	}
	t := transport.New(conn, transport.Options{})
	ctx := context.Background()
	var convID, guid []byte
	step := 0
	for {
		got, err := t.Receive(ctx)
		if err != nil {
			log(fmt.Sprintf("client closed: %v", err))
			return
		}
		switch {
		case len(got) == 64: // CONNECT: gateway normal-client record
			reply := append([]byte(nil), got...)
			reply[29] = 0x0f // protocol level accepted
			reply[55] = 0xfb // capability bits acknowledged
			if err := t.Send(reply); err != nil {
				return
			}
			log("CONNECT: gateway record acknowledged")
		case len(got) >= 48 && got[0] == 0x06 && got[1] == 0x03: // LOGON: CPIC-init
			convID = append([]byte(nil), got[40:48]...)
			guid = findRFCGUID(got)
			acc := patchSession(smartAccept, convID, guid)
			if err := t.Send(acc); err != nil {
				return
			}
			step = 0
			log(fmt.Sprintf("LOGON: accept generated (conv=%s guid=%x)", string(convID), guid))
		case len(got) > 80 && got[0] == 0x06 && got[1] == byte(0xcb): // SESSION: function request
			fn := "?"
			if req, err := DecodeCutFunctionRequest(got[80:]); err == nil {
				fn = req.FunctionName
			}
			switch fn {
			case "RFC_PING", "?": // the ping/RSRFCPIN dance (or an undecodable, assumed-ping frame)
				resp := patchSession(smartPingSteps[step%len(smartPingSteps)], convID, guid)
				if err := t.Send(resp); err != nil {
					return
				}
				log(fmt.Sprintf("SESSION: %s step %d answered", fn, step))
				step++
			default: // decoded, but no handler yet — fail cleanly instead of hanging
				uid := binary.BigEndian.Uint16(got[4:6])
				exc, _ := EncodeCutFunctionExceptionResponse("SYSTEM_FAILURE")
				wrapped, werr := wrapFSapSend(exc, convID, uid)
				if werr != nil {
					log("SESSION: wrap error: " + werr.Error())
					return
				}
				if err := t.Send(wrapped); err != nil {
					return
				}
				log(fmt.Sprintf("SESSION: %s not implemented -> SYSTEM_FAILURE", fn))
			}
		default: // control frames (80-byte turn/end, NI pings) need no reply
			log(fmt.Sprintf("(control %dB, no reply)", len(got)))
		}
	}
}

// patchSession returns a copy of a baked server record with this session's
// conversation id and RFC GUID substituted for the template's.
func patchSession(frame, convID, guid []byte) []byte {
	out := append([]byte(nil), frame...)
	if convID != nil {
		out = bytes.ReplaceAll(out, smartGoldenConv, convID)
	}
	if guid != nil {
		out = bytes.ReplaceAll(out, smartGoldenGUID, guid)
		out = bytes.ReplaceAll(out, swapRFCGUID(smartGoldenGUID), swapRFCGUID(guid))
	}
	return out
}
